from fastapi import FastAPI
from starlette.datastructures import URL
from starlette.responses import RedirectResponse
from starlette.types import ASGIApp, Receive, Scope, Send


redirector = FastAPI()


class Redirect2HTTPSPortMiddleware:
    def __init__(self, app: ASGIApp) -> None:
        self.app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] in ("http") and scope["scheme"] in ("http"):
            url = URL(scope=scope)
            redirect_scheme = {"http": "https"}[url.scheme]
            if (url.port == 80) or (url.port is None):  # handling default ports 80 --> 443
                new_url = url.replace(scheme=redirect_scheme, netloc=url.hostname)
            else:
                https_port = url.port + 1  # assuming HTTPS service is at next port
                new_url = url.replace(scheme=redirect_scheme, port=https_port)
            response = RedirectResponse(new_url, status_code=308)
            await response(scope, receive, send)
        else:
            await self.app(scope, receive, send)


redirector.add_middleware(Redirect2HTTPSPortMiddleware)
